<style>
.bl-farms-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr));gap:16px}
.bl-farm{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:20px;display:flex;flex-direction:column}
.bl-farm h3{font-size:1.25rem;color:var(--accent);margin-bottom:.2em;overflow-wrap:anywhere}
.bl-farm-loc{margin:0 0 12px;color:var(--muted);font-weight:600}
.bl-farm p{margin:0 0 .8em}
.bl-farm-facts{margin:auto 0 0;padding:12px 0 0 1.1em;border-top:1px dashed var(--line)}
.bl-farm-facts li{margin:0 0 .3em;overflow-wrap:anywhere}
</style>
<section class="section" id="farms" aria-labelledby="farms-h">
  <h2 id="farms-h">Our farms</h2>
  <p class="bl-note">The story behind our coffee, from three farms in Chikmagalur and Coorg.</p>
  <div class="bl-farms-grid">
    <article class="bl-farm" aria-labelledby="farm-ratnagiri-h">
      <h3 id="farm-ratnagiri-h">Ratnagiri Estate</h3>
      <p class="bl-farm-loc">Chikmagalur</p>
      <p>Ratnagiri Estate is a family estate. It grows its Arabica in the shade, at an altitude of 1,400 m.</p>
      <p>The estate is known for its natural-process lots, which have fruity notes.</p>
      <ul class="bl-farm-facts">
        <li>Family estate</li>
        <li>Shade-grown Arabica</li>
        <li>1,400 m</li>
        <li>Natural-process lots with fruity notes</li>
      </ul>
    </article>
    <article class="bl-farm" aria-labelledby="farm-kerehaklu-h">
      <h3 id="farm-kerehaklu-h">Kerehaklu</h3>
      <p class="bl-farm-loc">Chikmagalur</p>
      <p>Kerehaklu is a fourth-generation farm. It replants native forest trees on the land.</p>
      <p>Coffee here grows alongside pepper and cardamom.</p>
      <ul class="bl-farm-facts">
        <li>Fourth-generation farm</li>
        <li>Replants native forest trees</li>
        <li>Coffee grown alongside pepper and cardamom</li>
      </ul>
    </article>
    <article class="bl-farm" aria-labelledby="farm-baarbara-h">
      <h3 id="farm-baarbara-h">Baarbara Estate</h3>
      <p class="bl-farm-loc">Coorg</p>
      <p>Baarbara Estate is a small estate. Only ripe cherries are hand-picked.</p>
      <p>The cherries are then dried slowly on raised beds.</p>
      <ul class="bl-farm-facts">
        <li>Small estate</li>
        <li>Only ripe cherries, hand-picked</li>
        <li>Dried slowly on raised beds</li>
      </ul>
    </article>
  </div>
</section>
<!-- J2:W-2 end -->
<!-- J2:W-3 start (owner W-3) -->
<style>
.bl-po{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:20px;max-width:640px}
.bl-po-terms{margin:0 0 16px;padding:12px 14px;background:var(--bg);border-left:4px solid var(--accent);border-radius:6px}
.bl-po-terms p{margin:0 0 .3em}
.bl-po-terms p:last-child{margin:0}
.bl-po fieldset{border:0;margin:0 0 16px;padding:0;min-width:0}
.bl-po legend{font-weight:600;padding:0;margin:0 0 8px}
.bl-po-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:8px 0;border-bottom:1px dashed var(--line)}
.bl-po-row:last-child{border-bottom:0}
.bl-po-row label{flex:1 1 auto;min-width:0;overflow-wrap:anywhere}
.bl-po-row input{flex:0 0 72px;width:72px}
.bl-po-name{display:block;font-weight:600;margin:0 0 6px}
.bl-po input[type=text],.bl-po input[type=number]{font:inherit;padding:10px;border:1px solid var(--muted);border-radius:8px;background:#fff;color:var(--ink)}
.bl-po input[type=text]{width:100%;margin-bottom:16px}
.bl-po-total{font-weight:600;margin:0 0 12px}
.bl-po-error{color:#a11d1d;background:#fdeeee;border:1px solid #e3b4b4;border-radius:8px;padding:10px 12px;margin:0 0 12px}
.bl-po-error[hidden]{display:none}
.bl-po button{font:inherit;border:0;cursor:pointer;width:100%}
</style>
<section class="section" id="preorder" aria-labelledby="preorder-h">
  <h2 id="preorder-h">Pre-order for pickup</h2>
  <div class="bl-po">
    <div class="bl-po-terms">
      <p><strong>Payment is at pickup.</strong></p>
      <p>Pickup is within 15 minutes of ordering.</p>
      <p>Your order opens as a WhatsApp message to Brew Lab. Send it to place the order.</p>
    </div>
    <form id="po-form" novalidate>
      <fieldset>
        <legend>Choose items and quantities</legend>
        <div class="bl-po-row"><label for="po-q0">Espresso (₹120)</label><input type="number" id="po-q0" min="0" max="20" step="1" value="0" inputmode="numeric" data-name="Espresso" data-price="120"></div>
        <div class="bl-po-row"><label for="po-q1">Cappuccino (₹180)</label><input type="number" id="po-q1" min="0" max="20" step="1" value="0" inputmode="numeric" data-name="Cappuccino" data-price="180"></div>
        <div class="bl-po-row"><label for="po-q2">Pour-over (₹220)</label><input type="number" id="po-q2" min="0" max="20" step="1" value="0" inputmode="numeric" data-name="Pour-over" data-price="220"></div>
        <div class="bl-po-row"><label for="po-q3">Cold brew (₹200)</label><input type="number" id="po-q3" min="0" max="20" step="1" value="0" inputmode="numeric" data-name="Cold brew" data-price="200"></div>
        <div class="bl-po-row"><label for="po-q4">Croissant (₹150)</label><input type="number" id="po-q4" min="0" max="20" step="1" value="0" inputmode="numeric" data-name="Croissant" data-price="150"></div>
        <div class="bl-po-row"><label for="po-q5">Banana bread (₹130)</label><input type="number" id="po-q5" min="0" max="20" step="1" value="0" inputmode="numeric" data-name="Banana bread" data-price="130"></div>
      </fieldset>
      <label class="bl-po-name" for="po-name">Your name</label>
      <input type="text" id="po-name" maxlength="60" autocomplete="name">
      <p class="bl-po-total" id="po-total" aria-live="polite">Total: ₹0</p>
      <p class="bl-po-error" id="po-error" role="alert" hidden></p>
      <button type="submit" class="btn">Send order on WhatsApp</button>
    </form>
  </div>
  <script>
  (function () {
    var form = document.getElementById('po-form');
    var nameEl = document.getElementById('po-name');
    var errEl = document.getElementById('po-error');
    var totalEl = document.getElementById('po-total');
    if (!form || !nameEl || !errEl || !totalEl) { return; }
    var inputs = form.querySelectorAll('input[type=number]');

    function readItems() {
      var items = [], bad = false, total = 0, i, el, raw, q, price;
      for (i = 0; i < inputs.length; i++) {
        el = inputs[i];
        raw = String(el.value).trim();
        if (raw === '') { continue; }
        q = Number(raw);
        if (!isFinite(q) || q % 1 !== 0 || q < 0 || q > 20) { bad = true; continue; }
        if (q > 0) {
          price = Number(el.getAttribute('data-price'));
          items.push({ name: el.getAttribute('data-name'), qty: q, price: price });
          total += q * price;
        }
      }
      return { items: items, bad: bad, total: total };
    }

    function updateTotal() {
      var r = readItems();
      totalEl.textContent = 'Total: \u20B9' + (r.bad ? 0 : r.total);
    }

    function showError(msg) { errEl.textContent = msg; errEl.hidden = false; }
    function clearError() { errEl.textContent = ''; errEl.hidden = true; }

    form.addEventListener('input', function () { updateTotal(); clearError(); });

    form.addEventListener('submit', function (e) {
      e.preventDefault();
      var r = readItems();
      var name = nameEl.value.replace(/\s+/g, ' ').trim();
      if (r.bad) { showError('Quantities must be whole numbers from 0 to 20.'); return; }
      if (r.items.length === 0) { showError('Please choose at least one item.'); return; }
      if (!name) { showError('Please enter your name.'); nameEl.focus(); return; }
      clearError();
      var lines = ['Brew Lab pickup order', 'Name: ' + name, 'Items:'], i;
      for (i = 0; i < r.items.length; i++) {
        lines.push('- ' + r.items[i].qty + ' x ' + r.items[i].name + ' (\u20B9' + (r.items[i].qty * r.items[i].price) + ')');
      }
      lines.push('Total: \u20B9' + r.total, 'Payment at pickup.');
      var url = 'https://wa.me/919845000000?text=' + encodeURIComponent(lines.join('\n'));
      var w = null;
      try { w = window.open(url, '_blank', 'noopener'); } catch (err) { w = null; }
      if (!w) { window.location.href = url; }
    });

    updateTotal();
  })();
  </script>
</section>
<!-- J2:W-3 end -->
</body>
</html>
